        .current_dir(root)
        .status()
        .unwrap()
        .success());
    assert!(Command::new("git")
        .args(["-c", "commit.gpgSign=false", "commit", "-q", "-m", "Initial commit"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
